function validate([moveTime]) {
  if (moveTime.length < 2 || moveTime.length > 750) return 'moveTime needs 2 to 750 rows.';
  const cols = moveTime[0].length;
  if (cols < 2 || cols > 750) return 'Each row needs 2 to 750 rooms.';
  if (moveTime.some(row => row.length !== cols)) return 'All rows must have the same length.';
  if (moveTime.some(row => row.some(v => v < 0 || v > 1000000000))) return 'Each moveTime value is from 0 to 10^9.';
  return null;
}

