function minTimeToReach(moveTime) {
  const rows = moveTime.length;
  const cols = moveTime[0].length;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  const heap = [];
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      while (true) {
        const left = 2 * parent + 1;
        const right = left + 1;
        let smallest = parent;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === parent) break;
        [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
        parent = smallest;
      }
    }
    return top;
  };

  dist[0][0] = 0;
  push([0, 0, 0]);
  while (heap.length > 0) {
    const [time, row, col] = pop();
    if (row === rows - 1 && col === cols - 1) {
      return time;
    }
    if (time > dist[row][col]) {
      continue;
    }
    const step = (row + col) % 2 + 1;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const r = row + dr;
      const c = col + dc;
      if (r < 0 || r >= rows || c < 0 || c >= cols) {
        continue;
      }
      const arrival = Math.max(time, moveTime[r][c]) + step;
      if (arrival < dist[r][c]) {
        dist[r][c] = arrival;
        push([arrival, r, c]);
      }
    }
  }
  return -1;
}

