function minTimeToReach(moveTime) {
  // States are (room, parity of the number of moves made so far): the next move costs 1 second
  // after an even number of moves and 2 after an odd number. Relax every state's moves until no
  // arrival time improves (a Bellman-Ford style fixed point), without any heap or grid-parity shortcut.
  const n = moveTime.length, m = moveTime[0].length;
  const reach = [0, 1].map(() => moveTime.map(row => row.map(() => Infinity)));
  reach[0][0][0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let p = 0; p < 2; p++) {
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
          const now = reach[p][i][j];
          if (now === Infinity) continue;
          for (const [x, y] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]]) {
            if (x < 0 || y < 0 || x >= n || y >= m) continue;
            const t = Math.max(now, moveTime[x][y]) + (p === 0 ? 1 : 2);
            if (t < reach[1 - p][x][y]) { reach[1 - p][x][y] = t; changed = true; }
          }
        }
      }
    }
  }
  return Math.min(reach[0][n - 1][m - 1], reach[1][n - 1][m - 1]);
}

