function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const rows = large ? 100 - pick(6) : 2 + pick(3);
  const cols = large ? 100 - pick(6) : 2 + pick(3);
  const style = pick(5);
  const cell = (i, j) => {
    if (style === 0) return pick(large ? 1000 : 12);
    if (style === 1) return pick(1000000001);
    if (style === 2) return rand() < 0.65 ? 0 : 1 + pick(large ? 5000 : 30);
    if (style === 3) return Math.max(0, 3 * (i + j) + pick(7) - 3);
    return rand() < 0.15 ? 1000000000 - pick(10) : 0;
  };
  return [Array.from({ length: rows }, (_, i) => Array.from({ length: cols }, (_, j) => cell(i, j)))];
}
